import re
def sub1(s,old,new,count=1):
    assert s.count(old)==count,(old[:90],s.count(old));return s.replace(old,new)
def subline(s,key,new):
    m=re.search(r"^"+re.escape(key)+r".*$",s,re.M);assert m,key
    return s[:m.start()]+new+s[m.end():]
